CREATE DATABASE dmv_source;
CREATE DATABASE dmv_target;
CREATE DATABASE dmv_empty_source;
CREATE DATABASE dmv_empty_target;
\getenv fixture_password POSTGRES_PASSWORD
CREATE ROLE dmv_limited LOGIN PASSWORD :'fixture_password';
GRANT EXECUTE ON FUNCTION pg_catalog.pg_control_system() TO dmv_limited;
\connect dmv_source
GRANT EXECUTE ON FUNCTION pg_catalog.pg_control_system() TO dmv_limited;
CREATE SCHEMA demo;
CREATE SCHEMA pgfoo;
CREATE TABLE pgfoo.observed(value text);
INSERT INTO pgfoo.observed VALUES ('A');
CREATE TABLE demo.rename_source(identifier numeric,label text);
INSERT INTO demo.rename_source VALUES(100000000000000000000.000001,'A '),(2,NULL),(2,NULL);
CREATE TABLE demo.same(id integer, value text, amount numeric);
INSERT INTO demo.same VALUES (1,'A ',99999999999999999999999999999999999.000001),(2,NULL,0),(2,NULL,0);
CREATE TABLE demo.changed(id integer,value text,amount numeric);
INSERT INTO demo.changed VALUES (1,'A',1),(2,'B',2),(2,'B',2);
CREATE TABLE demo.hidden(id integer,value text);
INSERT INTO demo.hidden VALUES (1,'SYNTHETIC-PRIVATE-MARKER-A');
CREATE TABLE demo.policy(id integer,value text);
INSERT INTO demo.policy VALUES(1,'RLS-A');
ALTER TABLE demo.policy ENABLE ROW LEVEL SECURITY;
CREATE POLICY subset ON demo.policy USING(id>100);
CREATE TABLE demo.unsupported(value jsonb);
INSERT INTO demo.unsupported VALUES('{"synthetic":true}');
CREATE TABLE demo.large(value text);
INSERT INTO demo.large SELECT repeat('A',1100000);
CREATE TABLE demo.empty_columns();
INSERT INTO demo.empty_columns DEFAULT VALUES;
GRANT USAGE ON SCHEMA demo TO dmv_limited;
GRANT SELECT ON demo.same,demo.changed,demo.policy TO dmv_limited;
\connect dmv_target
GRANT EXECUTE ON FUNCTION pg_catalog.pg_control_system() TO dmv_limited;
